// ==========================================================
// Guard de precios — ningún importe sin get_detail_servicios
// ==========================================================
const agentOutput = $input.first().json;
const outputText = agentOutput.output || '';
const steps = agentOutput.intermediateSteps || [];

const MAX_INTENTOS = 2;   // 1 respuesta + 1 reintento. Nunca más.
const LEYENDA = '📝 Precios vigentes para el corriente mes, sujeto a modificación para el mes próximo.';
const NODO_PRECIOS_PREVIOS = 'Select rows from a table4';  // precio ya validado en turnos anteriores

// --- lo que NO se juzga: bloques internos y frases que nombran "precio" sin decir uno ---
const SUMMARY_BLOCK = /【summary:[\s\S]*?】/g;
const ALERT_BLOCK   = /【alert:[\s\S]*?】/g;
const FRASES_SEGURAS = [
  /📝\s*Precios vigentes para el corriente mes[^\n]*/gi,
  /El precio puede variar al cambiar el mes/gi,
  /El precio depende del service que le corresponda[^\n]*/gi,
  /Prefiero no tirarte un n[uú]mero al azar[^\n]*/gi,
  /te paso el precio exacto/gi,
];
let texto = outputText.replace(SUMMARY_BLOCK, '').replace(ALERT_BLOCK, '');
for (const re of FRASES_SEGURAS) texto = texto.replace(re, ' ');

// --- detección de importes: UN solo barrido, así ningún número se cuenta dos veces ---
const NUM = '\\d{1,3}(?:[.,]\\d{3})+(?:[.,]\\d{1,2})?|\\d+(?:[.,]\\d{1,2})?';
const IMPORTE = new RegExp(
  '(?:ARS|USD|\\$)\\s*(' + NUM + ')'                                            + '|' +
  '(' + NUM + ')\\s*(?:pesos|ARS|USD)\\b'                                       + '|' +
  '(?<![\\w$.,])(\\d{1,3}(?:[.,]\\d{3})+(?:[.,]\\d{1,2})?)(?!\\s*(?:km|kil[oó]metros?|meses|mes|hs|horas?|min))',
  'gi'
);
const AFIRMA_PRECIO = /\b(el\s+precio\s+(?:total\s+)?(?:es|ser[ií]a|queda|sale)|precio\s+total\s*[:=]|tiene\s+un\s+costo\s+de|el\s+costo\s+es|el\s+total\s+(?:es|queda|sale)|ronda\s+los)/i;

function aNumero(txt) {
  let s = String(txt).trim().replace(/\s/g, '');
  const dec = Math.max(s.lastIndexOf('.'), s.lastIndexOf(','));
  if (dec > -1 && /[.,]\d{1,2}$/.test(s) && s.length - dec - 1 <= 2) {
    s = s.slice(0, dec).replace(/[.,]/g, '') + '.' + s.slice(dec + 1);
  } else {
    s = s.replace(/[.,]/g, '');
  }
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

const importes = [];
let m; IMPORTE.lastIndex = 0;
while ((m = IMPORTE.exec(texto)) !== null) {
  const n = aNumero(m[1] ?? m[2] ?? m[3]);
  if (n !== null && n >= 1000) importes.push({ crudo: m[0].trim(), valor: n });
}

// --- ¿corrió la tool en este turno? ---
const esLaTool = (t) => String(t || '').toLowerCase().replace(/[^a-z]/g, '').includes('getdetailservicios');
const detailStep = steps.find(s => esLaTool(s.action?.tool));

// --- todos los números que la tool devolvió (a cualquier profundidad del JSON) ---
const preciosValidos = new Set();
function cosechar(v) {
  if (v === null || v === undefined) return;
  if (typeof v === 'number') { preciosValidos.add(Math.round(v)); preciosValidos.add(Math.trunc(v)); return; }
  if (typeof v === 'string') {
    const re = new RegExp(NUM, 'g'); let x;
    while ((x = re.exec(v)) !== null) {
      const n = aNumero(x[0]);
      if (n !== null) { preciosValidos.add(Math.round(n)); preciosValidos.add(Math.trunc(n)); }
    }
    return;
  }
  if (Array.isArray(v)) return v.forEach(cosechar);
  if (typeof v === 'object') return Object.values(v).forEach(cosechar);
}
if (detailStep) {
  let obs = detailStep.observation;
  try { if (typeof obs === 'string') obs = JSON.parse(obs); } catch (e) {}
  cosechar(obs);
}

// Repetir un precio ya validado en un turno anterior es legítimo: intermediateSteps
// solo cubre el turno actual, así que el precio guardado también cuenta como fuente.
try {
  const fila = $(NODO_PRECIOS_PREVIOS).first()?.json || {};
  const previo = fila.precio ?? fila.price ?? fila.precio_service ?? null;
  if (previo !== null && previo !== '') cosechar(previo);
} catch (e) {}

const valido = (n) => preciosValidos.has(Math.round(n)) || preciosValidos.has(Math.trunc(n)) || preciosValidos.has(Math.ceil(n));
const inventados = [...new Set(importes.filter(i => !valido(i.valor)).map(i => i.crudo))];

// --- veredicto ---
let problema = null;
if (importes.length && !detailStep && inventados.length) {
  problema = { reason: 'precio_sin_tool', importes: importes.map(i => i.crudo) };
} else if (detailStep && inventados.length) {
  problema = { reason: 'precio_inventado', inventados };
}

if (!problema) {
  // El precio es legítimo. Si falta la leyenda obligatoria, se agrega antes de los bloques internos.
  let out = outputText, leyendaAgregada = false;
  if (importes.length && !/Precios vigentes para el corriente mes/i.test(outputText)) {
    let pos = outputText.length;
    const s = outputText.search(/【summary:/), a = outputText.search(/【alert:/);
    if (s >= 0) pos = s; else if (a >= 0) pos = a;
    out = (outputText.slice(0, pos).trimEnd() + '\n' + LEYENDA + '\n' + outputText.slice(pos)).trim();
    leyendaAgregada = true;
  }
  return [{ json: {
    action: 'passthrough',
    output: out,
    leyendaAgregada,
    afirmaPrecioSinImporte: !importes.length && AFIRMA_PRECIO.test(texto),
    intermediateSteps: steps
  } }];
}

if ($runIndex < MAX_INTENTOS - 1) {
  return [{ json: { action: 'force_recovery', ...problema, output: outputText, intermediateSteps: steps } }];
}

// Reintentos agotados: no dejamos pasar un importe sin verificar.
return [{ json: {
  action: 'passthrough',
  reason: 'max_reintentos_' + problema.reason,
  inventados: problema.inventados || [],
  importes: problema.importes || [],
  output: 'Dejame confirmar el precio exacto de tu service con un asesor y te respondo en un momento. 🙏',
  intermediateSteps: steps
} }];

